 90	
 91	        using var parser = CreateParser(input);
 92	
 93	        var headers = parser.ReadFields();
 94	        if (headers is null)
 95	        {
 96	            return "CSV file is empty.";
 97	        }
 98	
 99	        var filteredColumnIndex = Array.FindIndex(
100	            headers,
101	            header => string.Equals(header, clause.ColumnName, StringComparison.OrdinalIgnoreCase));
102	
103	        if (filteredColumnIndex < 0)
104	        {
105	            return $"Column not found: {clause.ColumnName}";
106	        }
107	
108	        await using var writer = CreateWriter(output);
109	        var allColumns = Enumerable.Range(0, headers.Length).ToArray();
110	        await writer.WriteLineAsync(BuildCsvRow(headers, allColumns)).ConfigureAwait(false);
111	
112	        while (!parser.EndOfData)
113	        {
114	            var fields = parser.ReadFields();
115	            if (fields is null)
116	            {
117	                continue;
118	            }
119	
120	            var candidateValue = filteredColumnIndex < fields.Length ? fields[filteredColumnIndex] : string.Empty;
121	            if (!clause.Matches(candidateValue))
122	            {
123	                continue;
124	            }
125	
126	            await writer.WriteLineAsync(BuildCsvRow(fields, allColumns)).ConfigureAwait(false);
127	        }
128	
129	        await writer.FlushAsync().ConfigureAwait(false);
130	        await output.FlushAsync().ConfigureAwait(false);
131	        return null;
