134	    private static string BuildCsvRow(IReadOnlyList<string> fields, IReadOnlyList<int> selectedIndexes)
135	    {
136	        var selectedFields = new string[selectedIndexes.Count];
137	        for (var i = 0; i < selectedIndexes.Count; i++)
138	        {
139	            var selectedIndex = selectedIndexes[i];
140	            selectedFields[i] = selectedIndex < fields.Count ? EscapeCsvField(fields[selectedIndex]) : string.Empty;
141	        }
142	
143	        return string.Join(",", selectedFields);
144	    }
