167	    private static string EscapeCsvField(string value)
168	    {
169	        if (value.Length == 0)
170	        {
171	            return string.Empty;
172	        }
173	
174	        var requiresQuoting = value.Contains(',') ||
175	            value.Contains('"') ||
176	            value.Contains('\r') ||
177	            value.Contains('\n');
178	
179	        if (!requiresQuoting)
180	        {
181	            return value;
182	        }
183	
184	        var escaped = value.Replace("\"", "\"\"");
185	        return $"\"{escaped}\"";
186	    }
