188	    private sealed record CsvWhereClause(string ColumnName, ComparisonOperator Operator, string LiteralValue)
189	    {
190	        public static bool TryParse(string whereExpression, out CsvWhereClause clause, out string errorMessage)
191	        {
192	            var trimmedExpression = whereExpression?.Trim() ?? string.Empty;
193	            if (trimmedExpression.Length == 0)
194	            {
195	                clause = default!;
196	                errorMessage = "Invalid where expression.";
197	                return false;
198	            }
199	
200	            foreach (var candidate in ComparisonOperator.All)
201	            {
202	                var operatorIndex = trimmedExpression.IndexOf(candidate.Symbol, StringComparison.Ordinal);
203	                if (operatorIndex < 0)
204	                {
205	                    continue;
206	                }
207	
208	                var columnName = trimmedExpression[..operatorIndex].Trim();
209	                var literalValue = trimmedExpression[(operatorIndex + candidate.Symbol.Length)..].Trim();
210	                if (columnName.Length == 0 || literalValue.Length == 0)
211	                {
212	                    break;
213	                }
214	
215	                clause = new CsvWhereClause(columnName, candidate, literalValue);
216	                errorMessage = string.Empty;
217	                return true;
218	            }
219	
220	            clause = default!;
221	            errorMessage = "Invalid where expression.";
222	            return false;
223	        }
224	
225	        public bool Matches(string? candidateValue)
226	        {
227	            var leftValue = candidateValue ?? string.Empty;
228	            if (TryCompareNumerically(leftValue, LiteralValue, out var comparison))
229	            {
230	                return Operator.Evaluate(comparison);
231	            }
232	
233	            comparison = string.CompareOrdinal(leftValue, LiteralValue);
234	            return Operator.Evaluate(comparison);
235	        }
236	
237	        private static bool TryCompareNumerically(string leftValue, string rightValue, out int comparison)
238	        {
239	            if (decimal.TryParse(leftValue, NumberStyles.Number, CultureInfo.InvariantCulture, out var leftNumber) &&
240	                decimal.TryParse(rightValue, NumberStyles.Number, CultureInfo.InvariantCulture, out var rightNumber))
241	            {
242	                comparison = decimal.Compare(leftNumber, rightNumber);
243	                return true;
244	            }
245	
246	            comparison = 0;
247	            return false;
248	        }
249	    }
